wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(112084005689814611700)
,p_plug_name=>'RFC1 - Habitaciones Disponibles'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(112011811967844451205)
,p_plug_display_sequence=>60
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
unistr('    TH.ID_TIPO AS id_Tipo_habitaci\00F3n,'),
unistr('    TH.NOMBRE_TIPO AS Tipo_habitaci\00F3n,'),
'    TH.COSTO_BAJA AS Costo_temporada_baja,',
'    TH.COSTO_ALTA AS Costo_temporada_alta,',
'    TH.DIMENSIONES,',
'    TH.TIPO_VISTA,',
'    TH.CANTIDAD_CAMAS,',
'    COUNT(H.NUMERO_HABITACION) AS HABITACIONES_DISPONIBLES',
'FROM TIPO_HABITACIONES TH',
'JOIN HABITACIONES H ',
'    ON TH.ID_TIPO = H.ID_TIPO ',
'    AND H.ID_HOTEL = :P1_ID_HOTEL',
'    AND H.ESTADO_HABITACION = ''ACTIVA''',
'WHERE TH.ID_HOTEL = :P1_ID_HOTEL',
'  AND NOT EXISTS (',
'    SELECT 1 FROM RESERVAS R',
'    WHERE R.ID_TIPO = TH.ID_TIPO',
'    AND R.ESTADO NOT IN (''CANCELADA'')',
'    AND R.FECHA_ENTRADA < TO_DATE(:P1_FECHA_SALIDA, ''YYYY-MM-DD'')',
'    AND R.FECHA_SALIDA > TO_DATE(:P1_FECHA_ENTRADA, ''YYYY-MM-DD'')',
'  )',
'GROUP BY ',
'    TH.ID_TIPO, TH.NOMBRE_TIPO, TH.COSTO_BAJA, ',
'    TH.COSTO_ALTA, TH.DIMENSIONES, TH.TIPO_VISTA, TH.CANTIDAD_CAMAS',
'ORDER BY TH.NOMBRE_TIPO'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_page_header=>'RFC1 - Habitaciones Disponibles'
);
