'  AND R.FECHA_ENTRADA >= TO_DATE(:P6_FECHA_INICIO, ''YYYY-MM-DD'')',
'  AND R.FECHA_ENTRADA <= TO_DATE(:P6_FECHA_FIN, ''YYYY-MM-DD'')',
'GROUP BY TH.NOMBRE_TIPO',
'ORDER BY COUNT(R.ID_RESERVA) DESC'))
