prompt --application/pages/page_00015
begin
wwv_flow_imp_page.create_page(
 p_id=>15
,p_name=>unistr('Admin-rese\00F1as')
,p_alias=>unistr('ADMIN-RESE\00D1AS')
,p_step_title=>unistr('Admin-rese\00F1as')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://proyecto4fbd.onrender.com'';',
'',
'let hotelSeleccionado = null;',
'let reservaSeleccionada = null;',
'let resenaDestacadaActual = null;',
'',
'',
'',
'function valorBooleano(valor) {',
'  return valor === true || valor === ''true'';',
'}',
'',
'function obtenerIdResena(resena) {',
'  return resena.reserva_id || resena._id || '''';',
'}',
'',
'function escaparHtml(texto) {',
'  if (texto === null || texto === undefined) return '''';',
'',
'  return String(texto)',
'    .replaceAll(''&'', ''&amp;'')',
'    .replaceAll(''<'', ''&lt;'')',
'    .replaceAll(''>'', ''&gt;'')',
'    .replaceAll(''"'', ''&quot;'')',
'    .replaceAll("''", ''&#039;'');',
'}',
'',
'function aplicarEstiloTarjeta(tarjeta, esDestacada, estaSeleccionada) {',
'  if (estaSeleccionada) {',
'    tarjeta.style.border = ''2px solid #0070e0'';',
'    tarjeta.style.background = ''#f0f7ff'';',
'    return;',
'  }',
'',
'  if (esDestacada) {',
'    tarjeta.style.border = ''2px solid #f5a623'';',
'    tarjeta.style.background = ''#fff8e6'';',
'    return;',
'  }',
'',
'  tarjeta.style.border = ''1px solid #ddd'';',
'  tarjeta.style.background = ''white'';',
'}',
'',
'function parsearRespuesta(texto) {',
'  if (!texto) return {};',
'',
'  try {',
'    return JSON.parse(texto);',
'  } catch (e) {',
'    return { raw: texto };',
'  }',
'}',
'',
'/* =========================',
unistr('   BUSCAR RESE\00D1AS'),
'========================= */',
'',
'function buscarResenas() {',
'  const hotel = document.getElementById(''buscar-hotel'').value.trim();',
'  const resultadoDiv = document.getElementById(''buscar-resultado'');',
'  const listaDiv = document.getElementById(''lista-resenas'');',
'',
'  if (!hotel) {',
'    resultadoDiv.innerHTML = ''<p style="color:red;">Por favor ingresa un ID de hotel.</p>'';',
'    return;',
'  }',
'',
unistr('  resultadoDiv.innerHTML = ''<p style="color:gray;">Buscando rese\00F1as...</p>'';'),
'  listaDiv.innerHTML = '''';',
'',
'  document.getElementById(''panel-acciones'').style.display = ''none'';',
'  document.getElementById(''rf7-resultado'').innerHTML = '''';',
'  document.getElementById(''rf8-resultado'').innerHTML = '''';',
'  document.getElementById(''rf9-resultado'').innerHTML = '''';',
'',
'  fetch(API_BASE + ''/hoteles/'' + hotel + ''/resenas?_='' + Date.now())',
'    .then(async function(res) {',
'      const texto = await res.text();',
'',
'      if (!res.ok) {',
'        throw new Error(''HTTP '' + res.status + '' - '' + texto);',
'      }',
'',
'      return parsearRespuesta(texto);',
'    })',
'    .then(function(data) {',
'      var resenas = Array.isArray(data) ? data : (data.resenas || []);',
'',
'      if (resenas.length === 0) {',
unistr('        resultadoDiv.innerHTML = ''<p style="color:orange;">No se encontraron rese\00F1as para este hotel.</p>'';'),
'        return;',
'      }',
'',
'      hotelSeleccionado = hotel;',
'      reservaSeleccionada = null;',
'      resenaDestacadaActual = null;',
'',
unistr('      // Identificar la rese\00F1a destacada actual'),
'      resenas.forEach(function(resena) {',
'        var reservaId = obtenerIdResena(resena);',
'',
'        if (valorBooleano(resena.destacada)) {',
'          resenaDestacadaActual = reservaId;',
'        }',
'      });',
'',
'      // Para cumplir RF9 visualmente: la destacada queda arriba',
'      resenas.sort(function(a, b) {',
'        var aDestacada = valorBooleano(a.destacada);',
'        var bDestacada = valorBooleano(b.destacada);',
'',
'        if (aDestacada && !bDestacada) return -1;',
'        if (!aDestacada && bDestacada) return 1;',
'',
'        var fechaA = a.fecha || '''';',
'        var fechaB = b.fecha || '''';',
'        return fechaB.localeCompare(fechaA);',
'      });',
'',
'      resultadoDiv.innerHTML =',
'        ''<p style="color:green;">'' +',
'        resenas.length +',
unistr('        '' rese\00F1a(s) encontrada(s). Selecciona una para gestionarla.</p>'';'),
'',
'      resenas.forEach(function(resena) {',
'        var reservaId = obtenerIdResena(resena);',
'        var esDestacada = valorBooleano(resena.destacada);',
'',
'        var calificacion = resena.calificacion || null;',
'        var comentario = resena.comentario || ''Sin comentario'';',
'        var fecha = resena.fecha ? resena.fecha.substring(0, 10) : ''Sin fecha'';',
'        var utiles = resena.votos_utilidad || 0;',
'',
'        var tieneRespuesta = resena.respuesta ? ''Con respuesta'' : '''';',
unistr('        var destacadaTexto = esDestacada ? ''\2B50 Destacada'' : '''';'),
'',
'        var respuestaMensaje =',
'          resena.respuesta && resena.respuesta.mensaje',
'            ? resena.respuesta.mensaje',
'            : '''';',
'',
'        var respuestaFecha =',
'          resena.respuesta && resena.respuesta.fecha',
'            ? resena.respuesta.fecha.substring(0, 10)',
'            : '''';',
'',
'        var estrellas = '''';',
'',
'        if (calificacion !== null) {',
'          var cal = Math.min(Math.max(Math.round(calificacion), 1), 5);',
unistr('          estrellas = ''Calificaci\00F3n: '' + cal + ''/5'';'),
'        } else {',
unistr('          estrellas = ''Sin calificaci\00F3n'';'),
'        }',
'',
'        var tarjeta = document.createElement(''div'');',
'',
'        tarjeta.setAttribute(''data-resena-id'', reservaId);',
'        tarjeta.setAttribute(''data-destacada'', esDestacada ? ''true'' : ''false'');',
'',
'        tarjeta.style.cssText =',
'          ''border-radius:8px; padding:12px; cursor:pointer; margin-bottom:0;'';',
'',
'        aplicarEstiloTarjeta(tarjeta, esDestacada, false);',
'',
'        tarjeta.innerHTML =',
'          ''<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">'' +',
'            ''<span style="font-weight:bold;">Reserva: '' + escaparHtml(reservaId) + ''</span>'' +',
'            ''<span style="font-size:12px; color:#888;">'' +',
'              escaparHtml(destacadaTexto) +',
unistr('              (destacadaTexto && tieneRespuesta ? '' \00B7 '' : '''') +'),
'              escaparHtml(tieneRespuesta) +',
'            ''</span>'' +',
'          ''</div>'' +',
'',
'          ''<div style="margin-bottom:4px; font-size:13px; color:#555;">'' +',
'            escaparHtml(estrellas) +',
unistr('            '' &nbsp;\00B7&nbsp; '' +'),
'            escaparHtml(fecha) +',
unistr('            '' &nbsp;\00B7&nbsp; \D83D\DC4D '' +'),
'            escaparHtml(utiles) +',
'          ''</div>'' +',
'',
'          ''<p style="margin:0; font-size:14px; color:#333;">'' +',
'            escaparHtml(comentario) +',
'          ''</p>'' +',
'',
'          (',
'            respuestaMensaje',
'              ? ''<div style="margin-top:10px; padding:10px; background:#eef6ff; border-left:4px solid #0070e0; border-radius:4px;">'' +',
'                  ''<div style="font-size:13px; font-weight:bold; color:#0070e0; margin-bottom:4px;">Respuesta del hotel '' +',
'                    escaparHtml(respuestaFecha) +',
'                  ''</div>'' +',
'                  ''<div style="font-size:14px; color:#333;">'' +',
'                    escaparHtml(respuestaMensaje) +',
'                  ''</div>'' +',
'                ''</div>''',
'              : ''''',
'          );',
'',
'        tarjeta.onclick = function() {',
'          document.querySelectorAll(''#lista-resenas > div'').forEach(function(t) {',
'            var tEsDestacada = t.getAttribute(''data-destacada'') === ''true'';',
'            aplicarEstiloTarjeta(t, tEsDestacada, false);',
'          });',
'',
'          aplicarEstiloTarjeta(tarjeta, esDestacada, true);',
'',
'          reservaSeleccionada = reservaId;',
'',
'          document.getElementById(''resena-seleccionada-id'').textContent = reservaId;',
'          document.getElementById(''panel-acciones'').style.display = ''block'';',
'',
'          document.getElementById(''rf7-resultado'').innerHTML = '''';',
'          document.getElementById(''rf8-resultado'').innerHTML = '''';',
'          document.getElementById(''rf9-resultado'').innerHTML = '''';',
'',
'          document.getElementById(''rf7-mensaje'').value =',
'            respuestaMensaje ? respuestaMensaje : '''';',
'',
'          document.getElementById(''panel-acciones'').scrollIntoView({',
'            behavior: ''smooth'',',
'            block: ''start''',
'          });',
'        };',
'',
'        listaDiv.appendChild(tarjeta);',
'      });',
'    })',
'    .catch(function(err) {',
'      console.error(''Error buscarResenas:'', err);',
'      resultadoDiv.innerHTML =',
unistr('        ''<p style="color:red;">Error al buscar rese\00F1as. Verifica el ID del hotel.</p>'';'),
'    });',
'}',
'',
'/* =========================',
unistr('   RF7 - RESPONDER RESE\00D1A'),
'========================= */',
'',
'function responderResena() {',
'  var mensaje = document.getElementById(''rf7-mensaje'').value.trim();',
'  var resultado = document.getElementById(''rf7-resultado'');',
'',
'  if (!hotelSeleccionado || !reservaSeleccionada) {',
'    resultado.innerHTML =',
unistr('      ''<p style="color:red;">Primero selecciona una rese\00F1a.</p>'';'),
'    return;',
'  }',
'',
'  if (!mensaje) {',
'    resultado.innerHTML =',
'      ''<p style="color:red;">Escribe un mensaje de respuesta.</p>'';',
'    return;',
'  }',
'',
'  resultado.innerHTML =',
'    ''<p style="color:gray;">Guardando respuesta...</p>'';',
'',
'  fetch(API_BASE + ''/hoteles/'' + hotelSeleccionado + ''/resenas/'' + reservaSeleccionada + ''/responder'', {',
'    method: ''PUT'',',
'    headers: {',
'      ''Content-Type'': ''application/json''',
'    },',
'    body: JSON.stringify({',
'      administrador_id: hotelSeleccionado,',
'      mensaje: mensaje',
'    })',
'  })',
'  .then(async function(res) {',
'    const texto = await res.text();',
'',
'    if (!res.ok) {',
'      throw new Error(''HTTP '' + res.status + '' - '' + texto);',
'    }',
'',
'    return parsearRespuesta(texto);',
'  })',
'  .then(function() {',
'    resultado.innerHTML =',
'      ''<p style="color:green;">Respuesta guardada exitosamente.</p>'';',
'',
'    setTimeout(function() {',
'      buscarResenas();',
'    }, 1000);',
'  })',
'  .catch(function(err) {',
'    console.error(''Error RF7:'', err);',
'    resultado.innerHTML =',
'      ''<p style="color:red;">Error guardando la respuesta: '' + escaparHtml(err.message) + ''</p>'';',
'  });',
'}',
'',
'/* =========================',
unistr('   RF8 - ELIMINAR RESE\00D1A'),
'========================= */',
'',
'function eliminarResenaAdmin() {',
'  var resultado = document.getElementById(''rf8-resultado'');',
'',
'  if (!hotelSeleccionado || !reservaSeleccionada) {',
'    resultado.innerHTML =',
unistr('      ''<p style="color:red;">Primero selecciona una rese\00F1a.</p>'';'),
'    return;',
'  }',
'',
unistr('  if (!confirm(''\00BFSeguro que deseas eliminar esta rese\00F1a? Esta acci\00F3n no se puede deshacer.'')) {'),
'    resultado.innerHTML =',
unistr('      ''<p style="color:orange;">No se elimin\00F3 la rese\00F1a.</p>'';'),
'    return;',
'  }',
'',
'  resultado.innerHTML =',
unistr('    ''<p style="color:gray;">Eliminando rese\00F1a...</p>'';'),
'',
'  fetch(API_BASE + ''/hoteles/'' + hotelSeleccionado + ''/resenas/'' + reservaSeleccionada, {',
'    method: ''DELETE''',
'  })',
'  .then(async function(res) {',
'    const texto = await res.text();',
'',
'    if (!res.ok) {',
'      throw new Error(''HTTP '' + res.status + '' - '' + texto);',
'    }',
'',
'    return parsearRespuesta(texto);',
'  })',
'  .then(function() {',
'    resultado.innerHTML =',
unistr('      ''<p style="color:green;">Rese\00F1a eliminada exitosamente.</p>'';'),
'',
'    document.getElementById(''panel-acciones'').style.display = ''none'';',
'',
'    if (resenaDestacadaActual === reservaSeleccionada) {',
'      resenaDestacadaActual = null;',
'    }',
'',
'    reservaSeleccionada = null;',
'',
'    setTimeout(function() {',
'      buscarResenas();',
'    }, 1000);',
'  })',
'  .catch(function(err) {',
'    console.error(''Error RF8:'', err);',
'    resultado.innerHTML =',
unistr('      ''<p style="color:red;">Error eliminando la rese\00F1a: '' + escaparHtml(err.message) + ''</p>'';'),
'  });',
'}',
'',
'/* =========================',
unistr('   RF9 - DESTACAR RESE\00D1A'),
'========================= */',
'',
'function destacarResena() {',
'  var resultado = document.getElementById(''rf9-resultado'');',
'',
'  if (!hotelSeleccionado || !reservaSeleccionada) {',
'    resultado.innerHTML =',
unistr('      ''<p style="color:red;">Primero selecciona una rese\00F1a.</p>'';'),
'    return;',
'  }',
'',
'  if (resenaDestacadaActual === reservaSeleccionada) {',
'    resultado.innerHTML =',
unistr('      ''<p style="color:orange;">Esta rese\00F1a ya est\00E1 marcada como destacada.</p>'';'),
'    return;',
'  }',
'',
'  if (resenaDestacadaActual && resenaDestacadaActual !== reservaSeleccionada) {',
'    var confirmar = confirm(',
unistr('      ''Este hotel ya tiene una rese\00F1a destacada: '' + resenaDestacadaActual +'),
unistr('      ''.\005Cn\005CnSi destacas la rese\00F1a '' + reservaSeleccionada +'),
unistr('      '', la rese\00F1a '' + resenaDestacadaActual +'),
unistr('      '' dejar\00E1 de estar destacada.\005Cn\005Cn\00BFDeseas continuar?'''),
'    );',
'',
'    if (!confirmar) {',
'      resultado.innerHTML =',
unistr('        ''<p style="color:orange;">No se realiz\00F3 ning\00FAn cambio. La rese\00F1a destacada actual se mantiene.</p>'';'),
'      return;',
'    }',
'  }',
'',
'  resultado.innerHTML =',
unistr('    ''<p style="color:gray;">Actualizando rese\00F1a destacada...</p>'';'),
'',
'  fetch(API_BASE + ''/hoteles/'' + hotelSeleccionado + ''/resenas/'' + reservaSeleccionada + ''/destacar'', {',
'    method: ''PUT''',
'  })',
'  .then(async function(res) {',
'    const texto = await res.text();',
'',
'    if (!res.ok) {',
'      throw new Error(''HTTP '' + res.status + '' - '' + texto);',
'    }',
'',
'    return parsearRespuesta(texto);',
'  })',
'  .then(function() {',
'    var anterior = resenaDestacadaActual;',
'',
'    resenaDestacadaActual = reservaSeleccionada;',
'',
'    if (anterior) {',
'      resultado.innerHTML =',
unistr('        ''<p style="color:green;">La rese\00F1a '' +'),
'        escaparHtml(reservaSeleccionada) +',
unistr('        '' fue marcada como destacada. La rese\00F1a '' +'),
'        escaparHtml(anterior) +',
unistr('        '' dej\00F3 de estar destacada.</p>'';'),
'    } else {',
'      resultado.innerHTML =',
unistr('        ''<p style="color:green;">Rese\00F1a marcada como destacada correctamente.</p>'';'),
'    }',
'',
'    setTimeout(function() {',
'      buscarResenas();',
'    }, 1300);',
'  })',
'  .catch(function(err) {',
'    console.error(''Error RF9:'', err);',
'    resultado.innerHTML =',
unistr('      ''<p style="color:red;">Error al destacar la rese\00F1a: '' + escaparHtml(err.message) + ''</p>'';'),
'  });',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'11'
,p_last_updated_by=>'CO_B165_SQL_S32'
,p_last_upd_yyyymmddhh24miss=>'20260526190323'
);
