,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT U.NOMBRE, U.APELLIDOS, U.CORREO, U.TELEFONO, C.DOCUMENTO',
'    INTO :P21_NOMBRE, :P21_APELLIDOS, :P21_CORREO, :P21_TELEFONO, :P21_DOCUMENTO',
'    FROM USUARIOS U',
'    JOIN CLIENTES C ON U.ID_USUARIO = C.ID_USUARIO',
'    WHERE U.ID_USUARIO = :P21_ID_BUSCAR;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P21_NOMBRE := NULL;',
'        :P21_APELLIDOS := NULL;',
'        :P21_CORREO := NULL;',
'        :P21_TELEFONO := NULL;',
'        :P21_DOCUMENTO := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203926922888855509)
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112203927880080855518)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Actualizar Cliente'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE USUARIOS SET',
'        NOMBRE = :P21_NOMBRE,',
'        APELLIDOS = :P21_APELLIDOS,',
'        CORREO = :P21_CORREO,',
'        TELEFONO = :P21_TELEFONO',
'    WHERE ID_USUARIO = :P21_ID_BUSCAR;',
'    ',
'    UPDATE CLIENTES SET',
'        DOCUMENTO = :P21_DOCUMENTO',
'    WHERE ID_USUARIO = :P21_ID_BUSCAR;',
'    ',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203927693304855516)
,p_process_success_message=>'Datos actualizados correctamente'
);
end;
