wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112203929000940855530)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Crear Reserva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_NOCHES NUMBER;',
'    V_TEMPORADA VARCHAR2(4);',
'    V_COSTO NUMBER;',
'    V_PRECIO NUMBER;',
'BEGIN',
'    -- Calcular noches',
'    V_NOCHES := TO_DATE(:P22_FECHA_SALIDA, ''MM/DD/YYYY'') - TO_DATE(:P22_FECHA_ENTRADA, ''MM/DD/YYYY'');',
'    ',
'    -- Determinar temporada',
'    IF TO_NUMBER(TO_CHAR(TO_DATE(:P22_FECHA_ENTRADA, ''MM/DD/YYYY''), ''MM'')) ',
'       IN (6, 7, 8, 12) THEN',
'        V_TEMPORADA := ''ALTA'';',
'        SELECT COSTO_ALTA INTO V_COSTO ',
'        FROM TIPO_HABITACIONES WHERE ID_TIPO = :P22_ID_TIPO;',
'    ELSE',
'        V_TEMPORADA := ''BAJA'';',
'        SELECT COSTO_BAJA INTO V_COSTO ',
'        FROM TIPO_HABITACIONES WHERE ID_TIPO = :P22_ID_TIPO;',
'    END IF;',
'    ',
'    V_PRECIO := V_COSTO * V_NOCHES;',
'    ',
'    INSERT INTO RESERVAS VALUES (',
'        :P22_ID_RESERVA,',
'        :P22_ID_CLIENTE,',
'        :P22_ID_TIPO,',
'        TO_DATE(:P22_FECHA_ENTRADA, ''MM/DD/YYYY''),',
'        TO_DATE(:P22_FECHA_SALIDA, ''MM/DD/YYYY''),',
'        :P22_ADULTOS,',
'        :P22_NINOS,',
'        V_PRECIO,',
'        ''ACTIVA'',',
'        V_NOCHES,',
'        V_TEMPORADA',
'    );',
'    ',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203928923453855529)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Reserva creada exitosamente',
''))
);
end;
/
