wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112203930855289855548)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cargar reserva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT ID_CLIENTE, ID_TIPO, FECHA_ENTRADA, FECHA_SALIDA,',
'           ADULTOS, NINOS, PRECIO_TOTAL, ESTADO, NUMERO_NOCHES, TEMPORADA',
'    INTO :P24_ID_CLIENTE, :P24_ID_TIPO, :P24_FECHA_ENTRADA, :P24_FECHA_SALIDA,',
'         :P24_ADULTOS, :P24_NINOS, :P24_PRECIO_TOTAL, :P24_ESTADO, :P24_NUMERO_NOCHES, :P24_TEMPORADA',
'    FROM RESERVAS',
'    WHERE ID_RESERVA = :P24_ID_RESERVA;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P24_ESTADO := ''No encontrada'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203929469135855534)
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112203930941638855549)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Modificar fechas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_NOCHES NUMBER;',
'    V_COSTO NUMBER;',
'    V_PRECIO NUMBER;',
'    V_TEMPORADA VARCHAR2(4);',
'BEGIN',
unistr('    -- Verificar que la reserva no est\00E9 cancelada'),
'    IF :P24_ESTADO = ''CANCELADA'' THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''No se puede modificar una reserva cancelada.'');',
'    END IF;',
'',
'    -- Calcular nuevas noches',
'    V_NOCHES := TO_DATE(:P24_FECHA_SALIDA, ''MM/DD/YYYY'') - TO_DATE(:P24_FECHA_ENTRADA, ''MM/DD/YYYY'');',
'',
'    -- Determinar temporada',
'    IF TO_NUMBER(TO_CHAR(TO_DATE(:P24_FECHA_ENTRADA, ''MM/DD/YYYY''), ''MM''))',
'       IN (6, 7, 8, 12) THEN',
'        V_TEMPORADA := ''ALTA'';',
'        SELECT COSTO_ALTA INTO V_COSTO',
'        FROM TIPO_HABITACIONES WHERE ID_TIPO = :P24_ID_TIPO;',
'    ELSE',
'        V_TEMPORADA := ''BAJA'';',
'        SELECT COSTO_BAJA INTO V_COSTO',
'        FROM TIPO_HABITACIONES WHERE ID_TIPO = :P24_ID_TIPO;',
'    END IF;',
'',
'    V_PRECIO := V_COSTO * V_NOCHES;',
'',
'    UPDATE RESERVAS SET',
'        FECHA_ENTRADA = TO_DATE(:P24_FECHA_ENTRADA, ''MM/DD/YYYY''),',
'        FECHA_SALIDA = TO_DATE(:P24_FECHA_SALIDA, ''MM/DD/YYYY''),',
'        NUMERO_NOCHES = V_NOCHES,',
'        PRECIO_TOTAL = V_PRECIO,',
'        TEMPORADA = V_TEMPORADA',
'    WHERE ID_RESERVA = :P24_ID_RESERVA;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203930651525855546)
,p_process_success_message=>'Fechas modificadas correctamente'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(112203931028386855550)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar Reserva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
unistr('    -- Verificar que falten m\00E1s de 3 d\00EDas para la entrada'),
'    IF TO_DATE(:P24_FECHA_ENTRADA, ''MM/DD/YYYY'') - SYSDATE < 3 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ',
unistr('        ''No se puede cancelar con menos de 3 d\00EDas de anticipaci\00F3n.'');'),
'    END IF;',
'',
'    UPDATE RESERVAS SET ESTADO = ''CANCELADA''',
'    WHERE ID_RESERVA = :P24_ID_RESERVA;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(112203930784439855547)
,p_process_success_message=>'Reserva cancelada correctamente'
);
end;
