unistr('              <th style="padding:10px;">Calificaci\00F3n Promedio</th>'),
unistr('              <th style="padding:10px;">Total Rese\00F1as</th>'),
'            </tr>',
'          </thead>',
'          <tbody>',
'            ${data.map((h, i) => `',
'              <tr style="border-bottom:1px solid #ddd; text-align:center;">',
