'                <td style="padding:10px;">${h.nombreHotel || h._id}</td>',
'                <td style="padding:10px;">${h.ciudad || ''-''}</td>',
'                <td style="padding:10px;"> ${h.calificacionPromedio.toFixed(1)}</td>',
unistr('                <td style="padding:10px;">${h.totalRese\00F1as}</td>'),
'              </tr>',
'            `).join('''')}',
'          </tbody>',
'        </table>`;',
'      container.innerHTML = tabla;',
'    })',
'    .catch(() => {',
'      document.getElementById(''rfc1-container'').innerHTML = ''<p style="color:red;">Error cargando datos.</p>'';',
'    });',
'}'))
,p_javascript_code_onload=>'cargarTopHoteles();'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
