prompt --application/pages/page_00027
begin
wwv_flow_imp_page.create_page(
 p_id=>27
,p_name=>'RFC3E3 - Perfil Comparativo por Ciudad'
,p_alias=>'RFC3E3-PERFIL-COMPARATIVO-POR-CIUDAD'
,p_step_title=>'RFC3E3 - Perfil Comparativo por Ciudad'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://proyecto4fbd.onrender.com'';',
'',
'function cargarComparativo() {',
'  const ciudad = document.getElementById(''rfc3-ciudad'').value.trim();',
'  if (!ciudad) {',
'    alert(''Por favor ingresa una ciudad'');',
'    return;',
'  }',
'  fetch(`${API_BASE}/rfc3/comparativo/${ciudad}`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''rfc3-container'');',
'      if (data.length === 0) {',
unistr('        container.innerHTML = ''<p>No hay hoteles con rese\00F1as en esa ciudad.</p>'';'),
'        return;',
'      }',
'      const promedioCiudad = data.reduce((sum, h) => sum + h.calificacionPromedio, 0) / data.length;',
'      let tabla = `',
'        <p><strong>Promedio de la ciudad:  ${promedioCiudad.toFixed(1)}</strong></p>',
'        <table style="width:100%; border-collapse:collapse;">',
'          <thead>',
'            <tr style="background:#0070e0; color:white;">',
'              <th style="padding:10px;">Hotel</th>',
unistr('              <th style="padding:10px;">Calificaci\00F3n Promedio</th>'),
unistr('              <th style="padding:10px;">Total Rese\00F1as</th>'),
'              <th style="padding:10px;">% con Respuesta</th>',
'              <th style="padding:10px;">% Destacadas</th>',
'              <th style="padding:10px;">Estado</th>',
'            </tr>',
'          </thead>',
'          <tbody>',
'            ${data.map(h => `',
'              <tr style="border-bottom:1px solid #ddd; text-align:center; background:${h.calificacionPromedio < promedioCiudad ? ''#fff3f3'' : ''white''}">',
'                <td style="padding:10px;">${h.nombreHotel || h._id}</td>',
'                <td style="padding:10px;"> ${h.calificacionPromedio.toFixed(1)}</td>',
unistr('                <td style="padding:10px;">${h.totalRese\00F1as}</td>'),
'                <td style="padding:10px;">${h.pctConRespuesta.toFixed(0)}%</td>',
'                <td style="padding:10px;">${h.pctDestacadas.toFixed(0)}%</td>',
'                <td style="padding:10px;">${h.calificacionPromedio < promedioCiudad ? '' Bajo promedio'' : ''OK''}</td>',
'              </tr>',
'            `).join('''')}',
'          </tbody>',
'        </table>`;',
'      container.innerHTML = tabla;',
'    })',
'    .catch(() => {',
'      document.getElementById(''rfc3-container'').innerHTML = ''<p style="color:red;">Error cargando datos.</p>'';',
'    });',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'11'
,p_last_updated_by=>'CO_B165_SQL_S30'
,p_last_upd_yyyymmddhh24miss=>'20260526025104'
);
