prompt --application/pages/page_00028
begin
wwv_flow_imp_page.create_page(
 p_id=>28
,p_name=>unistr('RF1E3- Crear Rese\00F1a')
,p_alias=>unistr('RF1E3-CREAR-RESE\00D1A')
,p_step_title=>unistr('RF1E3- Crear Rese\00F1a')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://proyecto4fbd.onrender.com'';',
'',
'function crearResena() {',
'  const hotel = document.getElementById(''rf1-hotel'').value.trim();',
'  const reserva = document.getElementById(''rf1-reserva'').value.trim();',
'  const cliente = document.getElementById(''rf1-cliente'').value.trim();',
'  const calificacion = parseInt(document.getElementById(''rf1-calificacion'').value);',
'  const comentario = document.getElementById(''rf1-comentario'').value.trim();',
'',
