prompt --application/pages/page_00030
begin
wwv_flow_imp_page.create_page(
 p_id=>30
,p_name=>unistr('RF4E3 Ver Rese\00F1as')
,p_alias=>unistr('RF4-VER-RESE\00D1AS')
,p_step_title=>unistr('RF4 Ver Rese\00F1as')
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://proyecto4fbd.onrender.com'';',
'',
'function verResenas() {',
'  const hotel = document.getElementById(''rf4-hotel'').value.trim();',
'  const orden = document.getElementById(''rf4-orden'').value;',
'',
'  if (!hotel) {',
'    alert(''Ingresa un ID de hotel'');',
'    return;',
'  }',
'',
'  fetch(`${API_BASE}/hoteles/${hotel}/resenas`)',
'    .then(res => res.json())',
'    .then(data => {',
'      const container = document.getElementById(''rf4-container'');',
'      if (data.length === 0) {',
unistr('        container.innerHTML = ''<p>No hay rese\00F1as para este hotel.</p>'';'),
'        return;',
'      }',
'',
'      if (orden === ''fecha'') {',
'        data.sort((a, b) => new Date(b.fecha) - new Date(a.fecha));',
'      } else {',
'        data.sort((a, b) => b.votos_utilidad - a.votos_utilidad);',
'      }',
'',
'      const visibles = data.filter(r => r.visible);',
'      container.innerHTML = visibles.map(r => `',
'        <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px; background:${r.destacada ? ''#fffbe6'' : ''white''}">',
'          ${r.destacada ? ''<span style="color:#f5a623;"> </span><br/>'' : ''''}',
'          <strong>${r.cliente_id}</strong>',
'          <span style="color:#888; font-size:0.85em; margin-left:10px;">${r.fecha ? new Date(r.fecha).toLocaleDateString(''es-CO'') : ''''}</span>',
'          <span style="margin-left:10px;">${r.calificacion}/5</span>',
unistr('          <span style="margin-left:10px; color:#888;"> ${r.votos_utilidad} \00FAtil</span>'),
'          <p style="margin-top:6px;">${r.comentario}</p>',
'          ${r.respuesta ? `<div style="background:#f5f5f5; padding:8px; border-radius:4px; margin-top:8px;"><strong>Respuesta del hotel:</strong><p>${r.respuesta.mensaje}</p></div>` : ''''}',
'        </div>',
'      `).join('''');',
'    })',
'    .catch(() => {',
unistr('      document.getElementById(''rf4-container'').innerHTML = ''<p style="color:red;">Error cargando rese\00F1as.</p>'';'),
'    });',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'11'
,p_last_updated_by=>'CO_B165_SQL_S30'
,p_last_upd_yyyymmddhh24miss=>'20260526033745'
);
