,p_plug_template=>wwv_flow_imp.id(112011821763215451211)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div>',
'  <input type="text" id="rf4-hotel" placeholder="ID Hotel (Ej: H001)" style="width:100%; margin-bottom:8px; padding:8px; border:1px solid #ddd; border-radius:4px;"/>',
'  <select id="rf4-orden" style="width:100%; margin-bottom:8px; padding:8px; border:1px solid #ddd; border-radius:4px;">',
'    <option value="fecha">Ordenar por Fecha</option>',
'    <option value="utilidad">Ordenar por Utilidad</option>',
'  </select>',
unistr('  <button type="button" onclick="verResenas()" style="background:#0070e0; color:white; padding:8px 16px; border:none; border-radius:4px; cursor:pointer;">Ver Rese\00F1as</button>'),
'  <div id="rf4-container" style="margin-top:16px;"></div>',
'</div>'))
